struct game_layout {
    void *the_world;
    char pad0[8];
    void *the_file_finder;
    void *the_entity_maker;
    void *the_anim_maker;
    void *gamefile;
    char pad1[8];
    void *mb;
    void *p_blank_material;
    char pad2[28];
    char script_mfg[12];
    char process_stack[12];
    char pad3[124];
    char level_prefix[8];
    char pad4[276];
    char movie_name[8];
    char heroname[16];
};

extern "C" void game_dtor(game_layout *, int) __asm__("_$_4game");

void game_dtor(game_layout *self, int deleting)
{
    free_mem(self->gamefile);
    if (self->mb)
        builtin_delete(self->mb);
    if (self->the_world) {
        unload(self);
        if (g_world_ptr)
            world_dtor(g_world_ptr, 3);
        g_world_ptr = 0;
    }
    g_random_ptr = 0;
    g_random_r_ptr = 0;
    if (g_anim_maker)
        (*(void (**)(void *, int))(*(char **)g_anim_maker + 12))(g_anim_maker, 3);
    g_anim_maker = 0;
    self->the_anim_maker = 0;
    if (g_entity_maker)
        (*(void (**)(void *, int))(*(char **)g_entity_maker + 12))(g_entity_maker, 3);
    g_entity_maker = 0;
    self->the_entity_maker = 0;
    if (g_file_finder)
        (*(void (**)(void *, int))(*(char **)g_file_finder + 12))(g_file_finder, 3);
    g_file_finder = 0;
    self->the_file_finder = 0;
    ((int *)nglTextureMgr)[4] = 0;
    if (self->p_blank_material)
        material_dtor(self->p_blank_material, 3);
    if (stash_open())
        stash_close(2);
    if (stash_using())
        stash_free(2);
    destruct_scripts();
    for (int i = 1; i >= 0; --i)
        string_dtor(self->heroname + i * 8, 0);
    string_dtor(self->movie_name, 2);
    string_dtor(self->level_prefix, 2);
    list_clear(self->process_stack);
    script_mfg_dtor(self->script_mfg, 2);
    if (deleting & 1)
        builtin_delete(self);
}
